/**
 * Blocker links between issues: the `issue_dependencies` rows and the issue reads on either side of them.
 *
 * Must call (do not reimplement): orgPredicate, livePredicate, toIssueDependency, toIssue, listLabelsForIssues
 */
import { and, asc, eq, inArray } from "drizzle-orm";
import { getDb, issueDependencies, issues } from "@/server/db";
import type { IssueRow } from "@/server/db";
import { livePredicate, orgPredicate } from "./base-repository";
import { brandId, toIssue, toIssueDependency } from "./_mappers";
import { listLabelsForIssues } from "./label-repository";
import type { IsoTimestamp, IssueId, OrgId, UserId } from "@/types/common";
import type { Issue, IssueDependency } from "@/types/issue";

export async function findDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<IssueDependency | null> {
  const row = getDb()
    .select()
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .get();
  return row ? toIssueDependency(row) : null;
}

/** Stores the link, or leaves an existing one untouched, and returns the stored row. */
export async function insertDependency(input: {
  orgId: OrgId;
  issueId: IssueId;
  blockerId: IssueId;
  createdBy: UserId;
  createdAt: IsoTimestamp;
}): Promise<IssueDependency> {
  getDb()
    .insert(issueDependencies)
    .values(input)
    .onConflictDoNothing()
    .run();

  const row = await findDependency(input.orgId, input.issueId, input.blockerId);
  if (!row) {
    throw new Error(`Dependency ${input.issueId} <- ${input.blockerId} not stored`);
  }
  return row;
}

/** Returns `true` when a link was removed and `false` when there was none. */
export async function deleteDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<boolean> {
  const removed = getDb()
    .delete(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .returning({ blockerId: issueDependencies.blockerId })
    .all();
  return removed.length > 0;
}

/** The ids every given issue is blocked by, one hop out. Feeds the cycle walk. */
export async function listBlockerIds(
  orgId: OrgId,
  issueIds: readonly IssueId[],
): Promise<readonly IssueId[]> {
  const rows = getDb()
    .select({ blockerId: issueDependencies.blockerId })
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        inArray(issueDependencies.issueId, [...issueIds]),
      ),
    )
    .all();
  return [...new Set(rows.map((row) => brandId<IssueId>(row.blockerId)))];
}

/** Live blockers of one issue, open or closed, in issue-number order. */
export async function listBlockerIssues(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select({ issue: issues })
    .from(issueDependencies)
    .innerJoin(
      issues,
      and(
        eq(issues.id, issueDependencies.blockerId),
        eq(issues.orgId, issueDependencies.orgId),
      ),
    )
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        livePredicate(issues.archivedAt, {}),
      ),
    )
    .orderBy(asc(issues.number))
    .all();

  return withLabels(
    orgId,
    rows.map((row) => row.issue),
  );
}

/** Every issue that `blockerId` blocks, archived or not; callers decide what counts. */
export async function listBlockedIssues(
  orgId: OrgId,
  blockerId: IssueId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select({ issue: issues })
    .from(issueDependencies)
    .innerJoin(
      issues,
      and(
        eq(issues.id, issueDependencies.issueId),
        eq(issues.orgId, issueDependencies.orgId),
      ),
    )
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .orderBy(asc(issues.number))
    .all();

  return withLabels(
    orgId,
    rows.map((row) => row.issue),
  );
}

async function withLabels(
  orgId: OrgId,
  rows: readonly IssueRow[],
): Promise<readonly Issue[]> {
  const labels = await listLabelsForIssues(
    orgId,
    rows.map((row) => brandId<IssueId>(row.id)),
  );
  return rows.map((row) =>
    toIssue(row, (labels[row.id] ?? []).map((label) => label.id)),
  );
}

