/**
 * "Blocked by" links between issues: who may add or drop one, the rules that keep the graph acyclic, the completion gate and the notice sent when a blocker closes.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, assertNotArchived, isLive, subscribe, notify
 */
import { subscribe } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived, isLive } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as dependencyRepo from "@/server/repositories/issue-dependency-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import { toIsoTimestamp } from "@/types/common";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { issueResource, requireFound } from "./_support";
import { notify } from "./notification-service";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Issue, IssueDependency, IssueStatus } from "@/types/issue";
import type { Actor } from "@/types/member";

type BlockerLink = {
  orgId: OrgId;
  issueId: IssueId;
  blockerId: IssueId;
};

/** Raised by the completion gate: the issue still has open blockers. */
export class IssueBlockedError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly blockerIds: readonly IssueId[]) {
    super(`Issue is blocked by ${blockerIds.length} open issue(s)`);
    this.name = "IssueBlockedError";
  }
}

function isClosedStatus(status: IssueStatus): boolean {
  return CLOSED_ISSUE_STATUSES.includes(status);
}

/** A blocker is open while it is live and its status is not closed. */
function isOpen(issue: Issue): boolean {
  return isLive(issue) && !isClosedStatus(issue.status);
}

/**
 * Records "`issueId` is blocked by `blockerId`". Adding a link that already
 * exists returns the stored link. Both issues must be live, and the new link
 * must not close a loop through any chain of existing links.
 */
export async function addBlocker(
  actor: Actor,
  input: BlockerLink,
): Promise<IssueDependency> {
  assertOrgScope(actor, input.orgId);

  const blocked = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  const blocker = requireFound(
    await issueRepo.findIssueById(input.orgId, input.blockerId),
    "Issue",
    input.blockerId,
  );
  assertCan(actor, "issue:update", issueResource(blocked));
  assertNotArchived("Issue", blocked.id, blocked);
  assertNotArchived("Issue", blocker.id, blocker);

  if (input.issueId === input.blockerId) {
    throw new Error(`Issue ${input.issueId} cannot block itself`);
  }

  const existing = await dependencyRepo.findDependency(
    input.orgId,
    input.issueId,
    input.blockerId,
  );
  if (existing) return existing;

  // The new edge closes a loop exactly when the blocker is already blocked, directly or transitively, by the issue.
  if (await reaches(input.orgId, input.blockerId, input.issueId)) {
    throw new Error(
      `Issue ${input.blockerId} is already blocked by ${input.issueId}; the link would form a cycle`,
    );
  }

  return dependencyRepo.insertDependency({
    orgId: input.orgId,
    issueId: input.issueId,
    blockerId: input.blockerId,
    createdBy: actor.userId,
    createdAt: toIsoTimestamp(new Date()),
  });
}

/** Returns `true` when a link was removed and `false` when there was none. */
export async function removeBlocker(
  actor: Actor,
  input: BlockerLink,
): Promise<boolean> {
  assertOrgScope(actor, input.orgId);

  const blocked = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(blocked));

  return dependencyRepo.deleteDependency(
    input.orgId,
    input.issueId,
    input.blockerId,
  );
}

/** The live blockers of `issueId`, open or closed, in issue-number order. */
export async function listBlockers(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  return dependencyRepo.listBlockerIssues(orgId, issueId);
}

/**
 * The completion gate. Throws `IssueBlockedError` listing every open blocker;
 * called before any status change to `done`.
 */
export async function assertUnblocked(
  orgId: OrgId,
  issueId: IssueId,
): Promise<void> {
  const open = (await dependencyRepo.listBlockerIssues(orgId, issueId)).filter(
    isOpen,
  );
  if (open.length > 0) {
    throw new IssueBlockedError(open.map((issue) => issue.id));
  }
}

/**
 * Tells the assignee of every issue that `blockerId` was holding back, once
 * nothing holds it back any more. Reads the stored state, so it must run after
 * the blocker has closed.
 */
export async function notifyUnblocked(
  orgId: OrgId,
  blockerId: IssueId,
  actorId: UserId | null,
): Promise<void> {
  const dependents = await dependencyRepo.listBlockedIssues(orgId, blockerId);

  for (const issue of dependents) {
    if (!isLive(issue) || isClosedStatus(issue.status)) continue;

    const assigneeId = issue.assigneeId;
    if (assigneeId === null) continue;

    const stillBlocked = (
      await dependencyRepo.listBlockerIssues(orgId, issue.id)
    ).some(isOpen);
    if (stillBlocked) continue;

    await notify(orgId, "issue_unblocked", [assigneeId], {
      title: "An issue is unblocked",
      body: `Issue ${issue.id} is no longer blocked`,
      href: `/issues/${issue.id}`,
      actorId,
    });
  }
}

/**
 * Whether `target` is reachable from `start` by following "blocked by" links.
 * Breadth-first, one repository read per level, each node visited once.
 */
async function reaches(
  orgId: OrgId,
  start: IssueId,
  target: IssueId,
): Promise<boolean> {
  const seen = new Set<IssueId>([start]);
  let frontier: readonly IssueId[] = [start];

  while (frontier.length > 0) {
    const blockers = await dependencyRepo.listBlockerIds(orgId, frontier);
    if (blockers.includes(target)) return true;

    frontier = blockers.filter((id) => !seen.has(id));
    for (const id of frontier) seen.add(id);
  }
  return false;
}

/**
 * Bus wiring: a blocker that closes, by status or by archive, releases the
 * issues it blocks. Registered from `event-registry`.
 */
export function registerIssueDependencyListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.status_changed", async (payload) => {
      if (isClosedStatus(payload.from) || !isClosedStatus(payload.to)) return;
      await notifyUnblocked(payload.orgId, payload.issueId, payload.actorId);
    }),
    subscribe("issue.archived", async (payload) => {
      // Archiving leaves the status alone, so an open status here means the
      // blocker was open right up to this archive.
      const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
      if (!issue || isClosedStatus(issue.status)) return;
      await notifyUnblocked(payload.orgId, payload.issueId, payload.actorId);
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}

