import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import { registerEventHandlers, unregisterEventHandlers } from "@/server/services/event-registry";
import * as issueService from "@/server/services/issue-service";
import * as dependencyService from "@/server/services/issue-dependency-service";
import * as notificationService from "@/server/services/notification-service";
import * as projectService from "@/server/services/project-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Issue } from "@/types/issue";

let cleanup: () => void;
let tenant: Tenant;
let other: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("deps", "growth");
  other = await createTenant("othr", "growth");
  registerEventHandlers();
});

afterAll(() => {
  unregisterEventHandlers();
  cleanup();
});

const orgId = () => tenant.org.id;

function make(title: string, assigneeId: Tenant["userIds"][keyof Tenant["userIds"]] | null = null): Promise<Issue> {
  return issueService.createIssue(
    tenant.actors.member,
    issueInput(orgId(), tenant.project.id, { title, assigneeId }),
  );
}

async function setStatus(issue: Issue, status: Issue["status"], actor = tenant.actors.member): Promise<Issue> {
  return issueService.changeIssueStatus(actor, { orgId: orgId(), issueId: issue.id, status });
}

async function unblockedFor(userKey: keyof Tenant["userIds"]) {
  const page = await notificationService.listNotifications(tenant.actors.owner, {
    orgId: orgId(),
    recipientId: tenant.userIds[userKey],
    unreadOnly: false,
    kind: ["issue_unblocked"],
    limit: 100,
    cursor: null,
  });
  return page.items;
}

describe("link rules", () => {
  it("stores a link once, with the acting user as creator", async () => {
    const a = await make("A link one");
    const b = await make("B link one");
    const link = await dependencyService.addBlocker(tenant.actors.member, { orgId: orgId(), issueId: a.id, blockerId: b.id });
    expect(link).toMatchObject({ orgId: orgId(), issueId: a.id, blockerId: b.id, createdBy: tenant.userIds.member });
    expect(typeof link.createdAt).toBe("string");

    const again = await dependencyService.addBlocker(tenant.actors.member, { orgId: orgId(), issueId: a.id, blockerId: b.id });
    expect(again).toEqual(link);
    expect(await dependencyService.listBlockers(tenant.actors.member, orgId(), a.id)).toHaveLength(1);
  });

  it("rejects direct and chained cycles and self-links without storing anything", async () => {
    const a = await make("Cyc A");
    const b = await make("Cyc B");
    const c = await make("Cyc C");
    await dependencyService.addBlocker(tenant.actors.member, { orgId: orgId(), issueId: a.id, blockerId: b.id });
    await dependencyService.addBlocker(tenant.actors.member, { orgId: orgId(), issueId: b.id, blockerId: c.id });

    await expect(dependencyService.addBlocker(tenant.actors.member, { orgId: orgId(), issueId: b.id, blockerId: a.id })).rejects.toThrow();
    await expect(dependencyService.addBlocker(tenant.actors.member, { orgId: orgId(), issueId: c.id, blockerId: a.id })).rejects.toThrow();
    await expect(dependencyService.addBlocker(tenant.actors.member, { orgId: orgId(), issueId: a.id, blockerId: a.id })).rejects.toThrow();

    expect(await dependencyService.listBlockers(tenant.actors.member, orgId(), b.id)).toHaveLength(1);
    expect(await dependencyService.listBlockers(tenant.actors.member, orgId(), c.id)).toHaveLength(0);
    expect(await dependencyService.listBlockers(tenant.actors.member, orgId(), a.id)).toHaveLength(1);
  });

  it("rejects archived endpoints", async () => {
    const a = await make("Arch A");
    const b = await make("Arch B");
    await issueService.archiveIssue(tenant.actors.member, orgId(), b.id);
    await expect(dependencyService.addBlocker(tenant.actors.member, { orgId: orgId(), issueId: a.id, blockerId: b.id })).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(dependencyService.addBlocker(tenant.actors.member, { orgId: orgId(), issueId: b.id, blockerId: a.id })).rejects.toBeInstanceOf(AlreadyArchivedError);
  });

  it("rejects unknown and foreign ids with not-found, and foreign orgs with tenant scope", async () => {
    const a = await make("Scope A");
    const foreign = await issueService.createIssue(
      other.actors.member,
      issueInput(other.org.id, other.project.id, { title: "Foreign issue" }),
    );
    await expect(dependencyService.addBlocker(tenant.actors.member, { orgId: orgId(), issueId: a.id, blockerId: foreign.id })).rejects.toBeInstanceOf(NotFoundError);
    await expect(dependencyService.addBlocker(tenant.actors.member, { orgId: orgId(), issueId: a.id, blockerId: "nope" as typeof a.id })).rejects.toBeInstanceOf(NotFoundError);
    await expect(dependencyService.addBlocker(tenant.actors.member, { orgId: other.org.id, issueId: a.id, blockerId: a.id })).rejects.toBeInstanceOf(TenantScopeError);
    await expect(dependencyService.listBlockers(tenant.actors.member, other.org.id, a.id)).rejects.toBeInstanceOf(TenantScopeError);
    expect(await dependencyService.listBlockers(tenant.actors.member, orgId(), a.id)).toHaveLength(0);
    expect(await dependencyService.removeBlocker(tenant.actors.member, { orgId: orgId(), issueId: a.id, blockerId: "nope" as typeof a.id })).toBe(false);
  });

  it("requires issue:update for add/remove and issue:read for list", async () => {
    const a = await make("Perm A");
    const b = await make("Perm B");
    await expect(dependencyService.addBlocker(tenant.actors.viewer, { orgId: orgId(), issueId: a.id, blockerId: b.id })).rejects.toBeInstanceOf(PermissionDeniedError);
    expect(await dependencyService.listBlockers(tenant.actors.viewer, orgId(), a.id)).toHaveLength(0);
    await dependencyService.addBlocker(tenant.actors.member, { orgId: orgId(), issueId: a.id, blockerId: b.id });
    await expect(dependencyService.removeBlocker(tenant.actors.viewer, { orgId: orgId(), issueId: a.id, blockerId: b.id })).rejects.toBeInstanceOf(PermissionDeniedError);
    expect(await dependencyService.listBlockers(tenant.actors.member, orgId(), a.id)).toHaveLength(1);
  });

  it("removeBlocker reports whether a link was removed, and lists in number order without archived blockers", async () => {
    const a = await make("Rm A");
    const b1 = await make("Rm B1");
    const b2 = await make("Rm B2");
    const b3 = await make("Rm B3");
    await dependencyService.addBlocker(tenant.actors.member, { orgId: orgId(), issueId: a.id, blockerId: b3.id });
    await dependencyService.addBlocker(tenant.actors.member, { orgId: orgId(), issueId: a.id, blockerId: b1.id });
    await dependencyService.addBlocker(tenant.actors.member, { orgId: orgId(), issueId: a.id, blockerId: b2.id });

    const listed = await dependencyService.listBlockers(tenant.actors.member, orgId(), a.id);
    expect(listed.map((i) => i.number)).toEqual([b1.number, b2.number, b3.number].sort((x, y) => x - y));

    await issueService.archiveIssue(tenant.actors.member, orgId(), b2.id);
    expect((await dependencyService.listBlockers(tenant.actors.member, orgId(), a.id)).map((i) => i.id)).not.toContain(b2.id);

    expect(await dependencyService.removeBlocker(tenant.actors.member, { orgId: orgId(), issueId: a.id, blockerId: b1.id })).toBe(true);
    expect(await dependencyService.removeBlocker(tenant.actors.member, { orgId: orgId(), issueId: a.id, blockerId: b1.id })).toBe(false);
  });
});

describe("completion gate", () => {
  it("rejects done while open blockers exist, listing exactly those, and leaves the issue unchanged", async () => {
    const d = await make("Gate D");
    const open = await make("Gate open");
    const closed = await make("Gate closed");
    await dependencyService.addBlocker(tenant.actors.member, { orgId: orgId(), issueId: d.id, blockerId: open.id });
    await dependencyService.addBlocker(tenant.actors.member, { orgId: orgId(), issueId: d.id, blockerId: closed.id });
    await setStatus(closed, "done");

    const err = await setStatus(d, "done").catch((e: unknown) => e);
    expect(err).toBeInstanceOf(dependencyService.IssueBlockedError);
    expect((err as dependencyService.IssueBlockedError).blockerIds).toEqual([open.id]);
    expect((err as { code: string }).code).toBe("conflict");

    const after = await issueService.getIssue(tenant.actors.member, orgId(), d.id);
    expect(after.issue.status).toBe("backlog");

    await expect(issueService.moveIssue(tenant.actors.member, { orgId: orgId(), issueId: d.id, toStatus: "done", toIndex: 0 })).rejects.toBeInstanceOf(dependencyService.IssueBlockedError);
    expect((await setStatus(d, "in_progress")).status).toBe("in_progress");
  });

  it("allows done once every blocker is closed, and allows other statuses regardless", async () => {
    const d = await make("Gate D2");
    const b = await make("Gate b2");
    await dependencyService.addBlocker(tenant.actors.member, { orgId: orgId(), issueId: d.id, blockerId: b.id });
    await setStatus(b, "canceled");
    expect((await setStatus(d, "done")).status).toBe("done");
  });
});

describe("unblocked notifications", () => {
  it("notifies the assignee once, when the last open blocker closes; never on closed-to-closed; not to the actor", async () => {
    const d = await make("Unb D", tenant.userIds.admin);
    const x = await make("Unb X");
    const z = await make("Unb Z");
    await dependencyService.addBlocker(tenant.actors.member, { orgId: orgId(), issueId: d.id, blockerId: x.id });
    await dependencyService.addBlocker(tenant.actors.member, { orgId: orgId(), issueId: d.id, blockerId: z.id });

    await setStatus(x, "done");
    expect(await unblockedFor("admin")).toHaveLength(0);

    await setStatus(z, "done");
    const items = await unblockedFor("admin");
    expect(items).toHaveLength(1);
    expect(items[0]).toMatchObject({ kind: "issue_unblocked", href: `/issues/${d.id}`, actorId: tenant.userIds.member, recipientId: tenant.userIds.admin });

    await setStatus(z, "canceled");
    expect(await unblockedFor("admin")).toHaveLength(1);
  });

  it("does not notify the actor who closed the blocker", async () => {
    const e = await make("Self E", tenant.userIds.admin);
    const y = await make("Self Y", tenant.userIds.admin);
    await dependencyService.addBlocker(tenant.actors.member, { orgId: orgId(), issueId: e.id, blockerId: y.id });
    const before = (await unblockedFor("admin")).length;
    await setStatus(y, "done", tenant.actors.admin);
    expect((await unblockedFor("admin")).length).toBe(before);
  });

  it("archiving an open blocker notifies, archiving a closed one does not, and reopen-then-close notifies again", async () => {
    const h = await make("Arch H", tenant.userIds.admin);
    const r = await make("Arch R");
    await dependencyService.addBlocker(tenant.actors.member, { orgId: orgId(), issueId: h.id, blockerId: r.id });

    await issueService.archiveIssue(tenant.actors.member, orgId(), r.id);
    expect((await unblockedFor("admin")).filter((n) => n.href === `/issues/${h.id}`)).toHaveLength(1);

    const g = await make("Arch G", tenant.userIds.admin);
    const v = await make("Arch V");
    await setStatus(v, "done");
    await dependencyService.addBlocker(tenant.actors.member, { orgId: orgId(), issueId: g.id, blockerId: v.id });
    await issueService.archiveIssue(tenant.actors.member, orgId(), v.id);
    expect((await unblockedFor("admin")).filter((n) => n.href === `/issues/${g.id}`)).toHaveLength(0);

    const k = await make("Re K", tenant.userIds.admin);
    const q = await make("Re Q");
    await dependencyService.addBlocker(tenant.actors.member, { orgId: orgId(), issueId: k.id, blockerId: q.id });
    await setStatus(q, "done");
    await setStatus(q, "in_progress");
    expect((await unblockedFor("admin")).filter((n) => n.href === `/issues/${k.id}`)).toHaveLength(1);
    await setStatus(q, "canceled");
    expect((await unblockedFor("admin")).filter((n) => n.href === `/issues/${k.id}`)).toHaveLength(2);
  });

  it("removing a link never notifies, and a muted kind receives nothing", async () => {
    const m = await make("Mute M", tenant.userIds.admin);
    const n = await make("Mute N");
    await dependencyService.addBlocker(tenant.actors.member, { orgId: orgId(), issueId: m.id, blockerId: n.id });
    const before = (await unblockedFor("admin")).length;
    await dependencyService.removeBlocker(tenant.actors.member, { orgId: orgId(), issueId: m.id, blockerId: n.id });
    expect((await unblockedFor("admin")).length).toBe(before);

    await dependencyService.addBlocker(tenant.actors.member, { orgId: orgId(), issueId: m.id, blockerId: n.id });
    await notificationService.updatePreference(tenant.actors.admin, {
      orgId: orgId(),
      userId: tenant.userIds.admin,
      kind: "issue_unblocked",
      inApp: false,
      email: false,
      digestOnly: false,
    });
    await setStatus(n, "done");
    expect((await unblockedFor("admin")).length).toBe(before);
  });

  it("project archive cascade releases blocked issues of cascaded open blockers", async () => {
    const project = await projectService.createProject(tenant.actors.admin, {
      orgId: orgId(),
      name: "Cascade",
      slug: "cascade-x",
      key: "CSX",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    const blocker = await issueService.createIssue(
      tenant.actors.member,
      issueInput(orgId(), project.id, { title: "Cascade blocker" }),
    );
    const held = await make("Cascade held", tenant.userIds.admin);
    await dependencyService.addBlocker(tenant.actors.member, { orgId: orgId(), issueId: held.id, blockerId: blocker.id });

    const before = (await unblockedFor("admin")).length;
    await projectService.archiveProject(tenant.actors.admin, { orgId: orgId(), projectId: project.id, archiveIssues: true });
    const items = await unblockedFor("admin");
    expect(items.length).toBe(before + 1);
    expect(items.at(-1)).toMatchObject({ href: `/issues/${held.id}`, actorId: tenant.userIds.admin });
  });
});

